/// <summary>
/// Handle event for RetailDiscountOffer table
/// MPJ_24248 Price Data Extract
/// </summary>
[ExtensionOf(TableStr(RetailPeriodicDiscount))]
final class METRetailPeriodicDiscountTable_Extension
{
}

Method.Source:
    /// <summary>
    /// COC update
    /// </summary>
    public void update()
    {
        boolean     statusUpdated = false;
        
        if( this.IsGUPDiscount == NoYes::Yes
        && (this.PeriodicDiscountType == RetailDiscountOfferTypeBase::Multibuy || this.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer)
        &&  this.Status != this.orig().Status)
        {
            statusUpdated = true;
        }

        next update();

        if(statusUpdated) 
        {
            if(this.Status == RetailDisabledEnabled::Enabled)
            {
                RetailPeriodicDiscount::METTrackChangeEnabled(this.OfferId, SysAppCRUDOperation::Update);
            }
            else
            {
                RetailPeriodicDiscount::METTrackChangeDisabled(this.OfferId, SysAppCRUDOperation::Update);
            }
        }
    }

    /// <summary>
    /// COC insert
    /// </summary>
    public void insert()
    {
        next insert();

        if( this.IsGUPDiscount == NoYes::Yes
        && (this.PeriodicDiscountType == RetailDiscountOfferTypeBase::Multibuy || this.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer))
        {
            if(this.status == RetailDisabledEnabled::Enabled) //if first record is Disabled  not interested
            {
                RetailPeriodicDiscount::METTrackChangeEnabled(this.OfferId, SysAppCRUDOperation::Create);
            }
        }
    }

    /// <summary>
    /// Track the change
    /// </summary>
    /// <param name = "_OfferId">Discount id</param>
    /// <param name = "_crud">DB operation</param>
    public static void METTrackChangeEnabled(RetailOfferIdEx3 _OfferId, SysAppCRUDOperation _crud)
    {
        //Find base table and add to container of variables. Unpacking Inheritance based table to Common gives null values
        RetailPeriodicDiscount  retailPeriodicDiscountLoc;

        retailPeriodicDiscountLoc = RetailPeriodicDiscount::findByOfferId(_OfferId);

        Global::runAsync(classNum(METPriceChangeEventManage),
                        staticMethodStr(METPriceChangeEventManage, processEvent),
                        [METPriceChangeType::DiscountEnabled, retailPeriodicDiscountLoc, _crud],
                        System.Threading.CancellationToken::None,
                        classNum(METPriceChangeEventManage),
                        staticMethodStr(METPriceChangeEventManage, callBackResult));
        
    }

    /// <summary>
    /// Track the change. Run in real time instead of seperate thread. Force user to wait while we capture existing state before changes are made
    /// </summary>
    /// <param name = "_OfferId">Discount id</param>
    /// <param name = "_crud">DB operation</param>
    public static void METTrackChangeDisabled(RetailOfferIdEx3 _OfferId, SysAppCRUDOperation _crud)
    {
        //Find base table and add to container of variables. Unpacking Inheritance based table to Common gives null values
        RetailPeriodicDiscount  retailPeriodicDiscountLoc;
        container   resultCon;

        retailPeriodicDiscountLoc = RetailPeriodicDiscount::findByOfferId(_OfferId);

        resultCon = SysOperationSandbox::callStaticMethod(classNum(METPriceChangeEventManage),staticMethodStr(METPriceChangeEventManage,processEvent),
            [METPriceChangeType::DiscountDisabled, retailPeriodicDiscountLoc, _crud], "@MET:WaitingPriceChangeTrackingProcess", "@MET:ProcessCompleted");

        METPriceChangeEventManage::buildResultMessage(resultCon);
    }
